<?php

function main() {
    $input = trim(fgets(STDIN));
    if ($input === '') return;
    list($n, $k) = explode(' ', $input);
    $n = (int)$n;
    $k = (int)$k;

    // Compute m = min(n, largest m such that m! <= k)
    // Actually, we need the smallest m such that m! >= k? No.
    // We fix the first n-m elements as 1..n-m.
    // The last m elements are a permutation of n-m+1 .. n.
    // We need m such that m! >= k. We want the smallest m.
    // But m cannot exceed n.
    // If n! < k, output -1.
    // Since n can be up to 1e9, we can't compute n!.
    // Factorials grow fast. 20! > 2e18 > 1e9.
    // So if n >= 20, n! >= 20! > 1e9 >= k (since k <= 1e9).
    // So for n >= 20, permutation always exists.
    // For n < 20, we check if n! < k.

    $fact = [1];
    for ($i = 1; $i <= 20; $i++) {
        $fact[$i] = $fact[$i-1] * $i;
    }

    if ($n < 20 && $fact[$n] < $k) {
        echo "-1\n";
        return;
    }

    // Determine m
    $m = 0;
    while ($m <= 20 && $fact[$m] < $k) {
        $m++;
    }
    if ($m > $n) $m = $n; // Should not happen if logic correct, but safety.
    // Actually if n < 20, m is smallest with m! >= k. Since n! >= k, m <= n.
    // If n >= 20, m <= 20 <= n.

    $fixed_count = $n - $m;

    // Count lucky numbers <= fixed_count
    // Lucky numbers are composed of digits 4 and 7.
    // Max n is 1e9, so lucky numbers up to 10 digits (since 1e9 is 10 digits? 1,000,000,000 is 10 digits. Max lucky < 1e9 is 777,777,777 (9 digits). 4,444,444,444 > 1e9).
    // Generate all lucky numbers up to 1e9 (actually up to n, n <= 1e9).
    $lucky = [];
    function genLucky($cur, $limit, &$arr) {
        if ($cur > $limit) return;
        if ($cur > 0) $arr[] = $cur;
        genLucky($cur * 10 + 4, $limit, $arr);
        genLucky($cur * 10 + 7, $limit, $arr);
    }
    genLucky(0, $n, $lucky);
    sort($lucky);

    // Count lucky numbers in [1, fixed_count]
    $count_lucky_fixed = 0;
    foreach ($lucky as $l) {
        if ($l <= $fixed_count) $count_lucky_fixed++;
        else break;
    }

    // Now handle the last m positions: indices fixed_count+1 ... n
    // Values are fixed_count+1 ... n
    // We need the (k-1)-th permutation (0-indexed) of these m numbers.
    $values = range($fixed_count + 1, $n);
    $perm = [];
    $k_idx = $k - 1;
    $fact_m = $fact; // factorials up to m

    for ($i = $m; $i >= 1; $i--) {
        $f = $fact_m[$i - 1];
        $idx = (int)($k_idx / $f);
        $k_idx %= $f;
        $perm[] = $values[$idx];
        array_splice($values, $idx, 1);
    }

    // Count lucky indices i in [fixed_count+1, n] where perm[i - fixed_count - 1] is lucky
    $lucky_set = array_flip($lucky); // for O(1) lookup
    $count_lucky_tail = 0;
    for ($j = 0; $j < $m; $j++) {
        $pos = $fixed_count + 1 + $j;
        $val = $perm[$j];
        if (isset($lucky_set[$pos]) && isset($lucky_set[$val])) {
            $count_lucky_tail++;
        }
    }

    echo ($count_lucky_fixed + $count_lucky_tail) . "\n";
}

main();
